// =======================================================
// PASO 0: Función de utilidad para asegurar que la entrada es un array
// =======================================================

const ensureArray = (data) => {
    // Si la entrada es nula o indefinida, devolvemos un array vacío.
    if (!data) return []; 

    // Si es un objeto, pero no un array (ej. un solo registro), lo envolvemos.
    if (typeof data === 'object' && !Array.isArray(data)) {
        return [data];
    }
    // Si ya es un array, lo devolvemos.
    return Array.isArray(data) ? data : [];
};


// =======================================================
// PASO 1: Cargar y preparar los datos de entrada
// Asumiendo que el MERGE devuelve: Input 0 = valores, Input 1 = personas
// =======================================================

const inputItems = $input.all();

// Input 0: 'valores'
const valoresRaw = inputItems[0]?.json;
const valores = ensureArray(valoresRaw);

// Input 1: 'personas'
const personasRaw = inputItems[1]?.json;
const personas = ensureArray(personasRaw);


// =======================================================
// PASO 2: Crear un mapa de búsqueda para los 'valores' (PRIMA)
// =======================================================
const primaMap = new Map();
for (const item of valores) {
    // Utilizamos String() para asegurar que el tipo de clave sea consistente.
    if (item.numero_poliza) {
        primaMap.set(String(item.numero_poliza).trim(), item.PRIMA);
    }
}

// =======================================================
// PASO 3: Agrupación y Agregación (Simulación del .groupby().agg() de Pandas)
// =======================================================
const agrupadoMap = new Map();

for (const persona of personas) {
    // Limpieza y validación de la clave de agrupación
    const poliza = String(persona.numero_poliza || '').trim(); 
    if (!poliza || poliza.length === 0) continue; // Saltar si la clave está vacía

    if (!agrupadoMap.has(poliza)) {
        // Inicializar el nuevo grupo con los primeros valores (first)
        agrupadoMap.set(poliza, {
            numero_poliza: poliza,
            clave_agente: persona.clave_agente,
            codigo_producto: persona.codigo_producto,
            fecha_emision: persona.fecha_emision,
            nombre_producto: persona.nombre_producto,
            nombre_opcion_poliza: persona.nombre_opcion_poliza,
            tipo_documento: persona.tipo_documento,
            FECHA_PROCESO: persona.FECHA_PROCESO,
            // Sets para recoger valores únicos y simular join(', ').join(sorted(set(x)))
            NUMERO_DOCUMENTO: new Set(),
            NOMBRE: new Set(),
            CORREO_1: new Set(),
            CELULAR_1: new Set(),
        });
    }

    const grupo = agrupadoMap.get(poliza);

    // Limpieza de celular
    let celular = String(persona.CELULAR_1 || '').replace('.0', '').trim();
    if (celular) {
        grupo.CELULAR_1.add(celular);
    }
    
    // Recolección de valores únicos
    if (persona.NUMERO_DOCUMENTO) {
        grupo.NUMERO_DOCUMENTO.add(String(persona.NUMERO_DOCUMENTO).trim());
    }
    if (persona.NOMBRE) {
        grupo.NOMBRE.add(String(persona.NOMBRE).trim());
    }
    if (persona.CORREO_1) {
        grupo.CORREO_1.add(String(persona.CORREO_1).trim());
    }
}

let resultado = Array.from(agrupadoMap.values()).map(grupo => {
    
    // Función auxiliar para ordenar y unir los sets de valores
    const sortedSetToArray = (set) => Array.from(set).sort();
    
    const docList = sortedSetToArray(grupo.NUMERO_DOCUMENTO);
    const nameList = sortedSetToArray(grupo.NOMBRE);
    const mailList = sortedSetToArray(grupo.CORREO_1);
    const celularList = sortedSetToArray(grupo.CELULAR_1);

    // Obtener el primer celular único (o vacío)
    const celularUnico = celularList.length > 0 ? celularList[0] : '';
    
    return {
        // Campos 'first'
        numero_poliza: grupo.numero_poliza,
        clave_agente: grupo.clave_agente,
        codigo_producto: grupo.codigo_producto,
        fecha_emision: grupo.fecha_emision,
        nombre_producto: grupo.nombre_producto,
        nombre_opcion_poliza: grupo.nombre_opcion_poliza,
        tipo_documento: grupo.tipo_documento,
        FECHA_PROCESO: grupo.FECHA_PROCESO,
        
        // Campos agregados (unidos por coma)
        NUMERO_DOCUMENTO: docList.join(', '),
        NOMBRE: nameList.join(', '),
        CORREO_1: mailList.join(', '),
        CELULAR_1: celularUnico,
        
        // Prima (Merge/Left Join)
        Prima_totalizada: primaMap.get(grupo.numero_poliza) || 0,
    };
});


// =======================================================
// PASO 4: Implementar la función expandir_columna (Split)
// =======================================================
function expandirColumna(df, columnaBase, prefijo) {
    const expandedResults = [];

    for (const row of df) {
        const valoresRaw = String(row[columnaBase] || '');
        // Split, trim, y filtrar vacíos
        const listas = valoresRaw.split(',')
                                .map(i => i.trim())
                                .filter(i => i.length > 0);
        
        const newRow = { ...row };
        delete newRow[columnaBase]; 

        // Asignar los valores a las nuevas columnas dinámicas
        for (let i = 0; i < listas.length; i++) {
            newRow[`${prefijo}_${i + 1}`] = listas[i];
        }

        expandedResults.push(newRow);
    }
    return expandedResults;
}

// Aplicar la expansión al resultado (sobre NUMERO_DOCUMENTO)
resultado = expandirColumna(resultado, 'NUMERO_DOCUMENTO', 'Numero_documento');


// =======================================================
// PASO 5: Renombrar y seleccionar columnas finales
// =======================================================
const columnasFinales = [
    'emisiones', 'revision agente', 'codigo_producto', 'clave_agente', 'numero_poliza',
    'fecha_emision', 'nombre_producto', 'nombre_opcion_poliza', 'Prima_totalizada',
    'CORREO_1', 'Numero_documento_1', 'tipo_documento', 'Numero_documento_2',
    'FECG', 'telefono'
];

const resultadoFinal = resultado.map(row => {
    // Renombrar y asignar
    row.FECG = row.FECHA_PROCESO; 
    row.telefono = row.CELULAR_1; 
    
    const finalItem = {};

    for (const col of columnasFinales) {
        // Seleccionar las columnas, asignando '' si no existen.
        finalItem[col] = row[col] !== undefined ? row[col] : '';
    }

    return finalItem;
});


// =======================================================
// PASO 6: Devolver el resultado (¡CORREGIDO PARA ITERAR!)
// =======================================================

// Convertimos cada objeto del array 'resultadoFinal' en un objeto
// con la estructura { json: row } para generar un ítem de salida por cada registro.
return resultadoFinal.map(row => ({
    json: row
}));
